def algorithm(func, dim, lb, ub, budget, rng):
    n = int(np.sqrt(budget))
    x = rng.uniform(lb, ub, (n, dim))
    pop = [x.copy() for _ in range(n)]
    min_val = float('inf')
    best_x = None

    for t in range(1, budget+1):
        for i in range(n):
            y = pop[i].copy()
            idx = rng.choice([j for j in range(n) if j != i])
            v = pop[idx] + 0.5 * rng.normal(size=dim)
            for j in range(dim):
                if rng.random() < 0.5:
                    v[j] += rng.uniform(-1, 1)
                else:
                    v[j] -= rng.uniform(-1, 1)
                v[j] = np.clip(v[j], lb, ub)
            y = func(v)
            alpha = min(1 - t / budget, 0.99 ** (t // n))
            beta = rng.uniform(0, 1)
            if y < alpha * pop[i]:
                pop[i] = v
            elif beta > np.exp(-(y - pop[i]) / (10**(-8 + t/n))):
                pop[i] = v

        x_new = np.mean(pop, axis=0)
        x_new = func(x_new)
        if x_new < min_val:
            min_val = x_new
            best_x = x_new

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x = (ub - lb) * rng.rand(dim) + lb
    best_x = x.copy()
    best_y = func(x)

